?><section class="row page-section"><div class="col-lg-8 mx-auto"><div class="card"><div class="card-body p-4"><h5 class="page-title">Enroll face</h5><p class="text-muted">Capture one clear, front-facing face for <?php echo h(trim($trainee['first_name'].' '.$trainee['last_name'])); ?>.</p><div id="enrollStatus" class="alert alert-info">Loading local face recognition models…</div><video id="faceVideo" class="w-100 rounded bg-dark" autoplay muted playsinline></video><div class="mt-3 d-flex gap-2"><button class="btn btn-primary" id="captureFace" disabled>Capture &amp; Save</button><a class="btn btn-outline-secondary" href="trainees.php">Back</a></div></div></div></div></section><script src="https://cdn.jsdelivr.net/npm/face-api.js@0.22.2/dist/face-api.min.js"></script><script>document.addEventListener('DOMContentLoaded',async function(){const s=document.getElementById('enrollStatus'),v=document.getElementById('faceVideo'),b=document.getElementById('captureFace'),base='<?php echo h(base_url('assets/vendor/face-api/models')); ?>';try{await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri(base),faceapi.nets.faceLandmark68Net.loadFromUri(base),faceapi.nets.faceRecognitionNet.loadFromUri(base)]);v.srcObject=await navigator.mediaDevices.getUserMedia({video:true});s.textContent='Camera ready. Keep one face centered, then capture.';s.className='alert alert-success';b.disabled=false;}catch(e){s.textContent='Camera or face models are unavailable. Allow camera access and install the local model files.';s.className='alert alert-danger';}b.addEventListener('click',async()=>{b.disabled=true;s.textContent='Detecting face…';const d=await faceapi.detectSingleFace(v,new faceapi.TinyFaceDetectorOptions()).withFaceLandmarks().withFaceDescriptor();if(!d){s.textContent='No clear single face detected. Please try again.';s.className='alert alert-warning';b.disabled=false;return;}const r=await fetch('dtr_descriptors.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?php echo h(csrf_token()); ?>'},body:JSON.stringify({action:'save',trainee_id:<?php echo (int)$trainee['id']; ?>,descriptor:Array.from(d.descriptor)})});const out=await r.json();s.textContent=out.message||'Face enrollment failed.';s.className=out.ok?'alert alert-success':'alert alert-danger';b.disabled=false;});});</script><?php require_once __DIR__.'/../../includes/footer.php'; ?>
